import { Hono } from "hono";
import type { AppVariables, Env } from "../../../src/types";
import { AppError } from "../../../src/lib/errors";
import { requireModuleEnabled } from "../../../src/lib/modules";
import {
  auditWork, camelize, camelizeRows, cleanString, newId, nextTaskNumber, parseBool, parseJson,
  parseLimit, parseOffset, requireContact, requireOrgUser, requireProject, requireTask, requireTeam,
  requiredString, workAccess, type WorkContext,
} from "./common";
import { handleWorkWhatsAppWebhook, notifyWork } from "./notifications";
import { appendChatMessage, ensureChatAccess, hubChat, messageType, safeFileName } from "./chat";

export const workRoutes = new Hono<{Bindings:Env;Variables:AppVariables}>();
export const workPublicRoutes = new Hono<{Bindings:Env;Variables:AppVariables}>();

const TASK_STATUSES = ["backlog","todo","in_progress","blocked","in_review","completed","cancelled"] as const;
const PRIORITIES = ["low","medium","high","urgent"] as const;
const PROJECT_STATUSES = ["planning","active","on_hold","completed","cancelled"] as const;
const actor = (c: WorkContext) => c.get("principal").userId.startsWith("apikey:") ? null : c.get("principal").userId;
const choice = <T extends readonly string[]>(value: unknown, values: T, fallback: T[number]) => values.includes(String(value) as T[number]) ? String(value) as T[number] : fallback;
const list = (value: unknown) => Array.isArray(value) ? [...new Set(value.filter((x):x is string=>typeof x==="string"&&x.length>0))] : [];

workPublicRoutes.post("/whatsapp", c => handleWorkWhatsAppWebhook(c.req.raw,c.env));

workRoutes.use("*", requireModuleEnabled("tasks-work"));
workRoutes.use("*", workAccess("read"));

workRoutes.get("/manifest", c => c.json({data:{
  key:"tasks-work",name:"Tasks & Work",version:"1.0.0",
  features:["teams","contacts","projects","tasks","subtasks","assignees","followers","checklists","comments","mentions","time-tracking","notifications","reminders","whatsapp-webhook"],
  communications:["resend","egosms","ulib-whatsapp-hub"],source:"kawalyauma/tasks-work-backend",sourceCommit:"19bda3eee6018bd2f5631a1353adcd71ad366da9",
}}));

workRoutes.get("/organization", async c => {
  const p=c.get("principal");
  const row=await c.env.FINANCE_DB.prepare("SELECT id,name,timezone,status,created_at FROM organizations WHERE id=?").bind(p.organizationId).first<Record<string,unknown>>();
  return c.json({data:row?camelize(row):null});
});
workRoutes.get("/members", async c => {
  const p=c.get("principal");
  const r=await c.env.FINANCE_DB.prepare(`SELECT u.id,u.display_name AS full_name,u.email,u.status,m.role,
      COALESCE(sf.phone,sp.phone) AS phone,COALESCE(sf.staff_number,sp.staff_number) AS staff_number,
      sf.id AS staff_id,sf.is_teacher,sf.employment_status,dp.name AS department_name,pos.name AS position_name
    FROM memberships m JOIN users u ON u.id=m.user_id
    LEFT JOIN school_user_profiles sp ON sp.organization_id=m.organization_id AND sp.user_id=m.user_id
    LEFT JOIN school_staff_profiles sf ON sf.organization_id=m.organization_id AND sf.user_id=m.user_id AND sf.deleted_at IS NULL
    LEFT JOIN school_departments dp ON dp.id=sf.department_id
    LEFT JOIN school_staff_positions pos ON pos.id=sf.position_id
    WHERE m.organization_id=? AND u.status='active' ORDER BY u.display_name`).bind(p.organizationId).all<Record<string,unknown>>();
  return c.json({data:camelizeRows(r.results)});
});

// DASHBOARD
workRoutes.get("/dashboard", async c => {
  const p=c.get("principal"),uid=p.userId;
  const [taskStats,projectStats,myDue,recent,unread,time] = await Promise.all([
    c.env.FINANCE_DB.prepare(`SELECT COUNT(*) total,
      SUM(status='completed') completed,SUM(status='in_progress') in_progress,SUM(status='blocked') blocked,
      SUM(status NOT IN ('completed','cancelled') AND due_at IS NOT NULL AND datetime(due_at)<datetime('now')) overdue
      FROM work_tasks WHERE organization_id=? AND archived_at IS NULL`).bind(p.organizationId).first<Record<string,unknown>>(),
    c.env.FINANCE_DB.prepare(`SELECT COUNT(*) total,SUM(status='active') active,SUM(status='completed') completed FROM work_projects WHERE organization_id=? AND archived_at IS NULL`).bind(p.organizationId).first<Record<string,unknown>>(),
    c.env.FINANCE_DB.prepare(`SELECT t.id,t.task_number,t.title,t.status,t.priority,t.due_at,pj.name project_name FROM work_tasks t
      JOIN work_task_assignees a ON a.task_id=t.id LEFT JOIN work_projects pj ON pj.id=t.project_id
      WHERE t.organization_id=? AND a.user_id=? AND t.archived_at IS NULL AND t.status NOT IN ('completed','cancelled')
      ORDER BY t.due_at IS NULL,t.due_at LIMIT 8`).bind(p.organizationId,uid).all<Record<string,unknown>>(),
    c.env.FINANCE_DB.prepare(`SELECT t.id,t.task_number,t.title,t.status,t.priority,t.updated_at,pj.name project_name FROM work_tasks t LEFT JOIN work_projects pj ON pj.id=t.project_id WHERE t.organization_id=? AND t.archived_at IS NULL ORDER BY t.updated_at DESC LIMIT 8`).bind(p.organizationId).all<Record<string,unknown>>(),
    c.env.FINANCE_DB.prepare("SELECT COUNT(*) count FROM work_notifications WHERE organization_id=? AND user_id=? AND read_at IS NULL").bind(p.organizationId,uid).first<{count:number}>(),
    c.env.FINANCE_DB.prepare(`SELECT COALESCE(SUM(minutes),0) minutes FROM work_time_entries WHERE organization_id=? AND user_id=? AND datetime(started_at)>=datetime('now','-7 days')`).bind(p.organizationId,uid).first<{minutes:number}>(),
  ]);
  return c.json({data:{tasks:camelize(taskStats||{}),projects:camelize(projectStats||{}),myDue:camelizeRows(myDue.results),recent:camelizeRows(recent.results),unreadNotifications:Number(unread?.count||0),myMinutesLast7Days:Number(time?.minutes||0)}});
});

// TEAMS
workRoutes.get("/teams", async c => {
  const p=c.get("principal");
  const r=await c.env.FINANCE_DB.prepare(`SELECT t.*,u.display_name lead_name,(SELECT COUNT(*) FROM work_team_members tm WHERE tm.team_id=t.id) member_count
    FROM work_teams t LEFT JOIN users u ON u.id=t.lead_user_id WHERE t.organization_id=? AND t.status='active' ORDER BY t.name`).bind(p.organizationId).all<Record<string,unknown>>();
  return c.json({data:camelizeRows(r.results)});
});
workRoutes.post("/teams", workAccess("manage"), async c => {
  const p=c.get("principal"),body=await c.req.json<Record<string,unknown>>(),id=newId("wtm");
  const name=requiredString(body.name,"name",160),description=cleanString(body.description),leadUserId=cleanString(body.leadUserId,100);
  if(leadUserId)await requireOrgUser(c.env.FINANCE_DB,p.organizationId,leadUserId,"Team lead");
  await c.env.FINANCE_DB.prepare("INSERT INTO work_teams (id,organization_id,name,description,lead_user_id,created_by) VALUES (?,?,?,?,?,?)").bind(id,p.organizationId,name,description,leadUserId,actor(c)).run();
  if(leadUserId)await c.env.FINANCE_DB.prepare("INSERT OR IGNORE INTO work_team_members (team_id,user_id,role) VALUES (?,?,'lead')").bind(id,leadUserId).run();
  await auditWork(c.env.FINANCE_DB,c,"work.team.created","work_team",id,undefined,{name,description,leadUserId});
  return c.json({data:{id,name,description,leadUserId}},201);
});
workRoutes.get("/teams/:id", async c => {
  const p=c.get("principal"),team=await requireTeam(c.env.FINANCE_DB,p.organizationId,c.req.param("id"));
  const members=await c.env.FINANCE_DB.prepare(`SELECT u.id,u.display_name AS full_name,u.email,tm.role FROM work_team_members tm JOIN users u ON u.id=tm.user_id WHERE tm.team_id=? ORDER BY u.display_name`).bind(c.req.param("id")).all<Record<string,unknown>>();
  return c.json({data:{...camelize(team),members:camelizeRows(members.results)}});
});
workRoutes.patch("/teams/:id", workAccess("manage"), async c => {
  const p=c.get("principal"),id=c.req.param("id"),before=await requireTeam(c.env.FINANCE_DB,p.organizationId,id),body=await c.req.json<Record<string,unknown>>();
  const name=cleanString(body.name,160),description=body.description===null?null:cleanString(body.description),lead=body.leadUserId===null?null:cleanString(body.leadUserId,100);
  if(lead)await requireOrgUser(c.env.FINANCE_DB,p.organizationId,lead,"Team lead");
  await c.env.FINANCE_DB.prepare(`UPDATE work_teams SET name=COALESCE(?,name),description=CASE WHEN ? THEN ? ELSE description END,lead_user_id=CASE WHEN ? THEN ? ELSE lead_user_id END,updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=?`).bind(name,Object.hasOwn(body,"description")?1:0,description,Object.hasOwn(body,"leadUserId")?1:0,lead,id,p.organizationId).run();
  if(lead)await c.env.FINANCE_DB.prepare("INSERT OR REPLACE INTO work_team_members (team_id,user_id,role,created_at) VALUES (?,?,'lead',CURRENT_TIMESTAMP)").bind(id,lead).run();
  await auditWork(c.env.FINANCE_DB,c,"work.team.updated","work_team",id,before,body);return c.json({data:{id,updated:true}});
});
workRoutes.post("/teams/:id/members", workAccess("manage"), async c => {
  const p=c.get("principal"),teamId=c.req.param("id"),body=await c.req.json<Record<string,unknown>>();await requireTeam(c.env.FINANCE_DB,p.organizationId,teamId);
  const userId=requiredString(body.userId,"userId",100);await requireOrgUser(c.env.FINANCE_DB,p.organizationId,userId);
  const role=choice(body.role,["lead","manager","member","viewer"] as const,"member");
  await c.env.FINANCE_DB.prepare("INSERT INTO work_team_members (team_id,user_id,role) VALUES (?,?,?) ON CONFLICT(team_id,user_id) DO UPDATE SET role=excluded.role").bind(teamId,userId,role).run();
  await auditWork(c.env.FINANCE_DB,c,"work.team.member_upserted","work_team",teamId,undefined,{userId,role});return c.json({data:{teamId,userId,role}});
});
workRoutes.delete("/teams/:id/members/:userId", workAccess("manage"), async c => {
  const p=c.get("principal"),teamId=c.req.param("id");await requireTeam(c.env.FINANCE_DB,p.organizationId,teamId);
  await c.env.FINANCE_DB.prepare("DELETE FROM work_team_members WHERE team_id=? AND user_id=?").bind(teamId,c.req.param("userId")).run();
  return c.json({data:{removed:true}});
});
workRoutes.delete("/teams/:id", workAccess("manage"), async c => {const p=c.get("principal");const id=c.req.param("id");await requireTeam(c.env.FINANCE_DB,p.organizationId,id);await c.env.FINANCE_DB.prepare("UPDATE work_teams SET status='archived',updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=?").bind(id,p.organizationId).run();return c.json({data:{archived:true}})});

// SHARED PEOPLE / CONTACTS
// These endpoints intentionally use Ledgerly's core contacts/contact_people tables.
// The old work_contacts table is retained only as migration history and is no longer written.
workRoutes.get("/contacts", async c => {
  const p=c.get("principal"),limit=parseLimit(c),offset=parseOffset(c),search=`%${c.req.query("search")||""}%`,type=c.req.query("type")||null;
  const rows=await c.env.FINANCE_DB.prepare(`SELECT c.id,c.type,c.code,c.name,c.email,c.active,c.credit_limit_minor,c.pricing_tier,c.custom_fields,
      (SELECT cp.name FROM contact_people cp WHERE cp.organization_id=c.organization_id AND cp.contact_id=c.id ORDER BY cp.is_primary DESC,cp.created_at LIMIT 1) primary_person_name,
      (SELECT cp.phone FROM contact_people cp WHERE cp.organization_id=c.organization_id AND cp.contact_id=c.id ORDER BY cp.is_primary DESC,cp.created_at LIMIT 1) phone,
      (SELECT cp.role FROM contact_people cp WHERE cp.organization_id=c.organization_id AND cp.contact_id=c.id ORDER BY cp.is_primary DESC,cp.created_at LIMIT 1) primary_person_role,
      (SELECT COUNT(*) FROM contact_people cp WHERE cp.organization_id=c.organization_id AND cp.contact_id=c.id) people_count
    FROM contacts c WHERE c.organization_id=? AND c.archived_at IS NULL AND c.active=1
      AND (? IS NULL OR c.type=?)
      AND (c.name LIKE ? OR COALESCE(c.email,'') LIKE ? OR COALESCE(c.code,'') LIKE ? OR EXISTS(SELECT 1 FROM contact_people cp WHERE cp.organization_id=c.organization_id AND cp.contact_id=c.id AND (cp.name LIKE ? OR COALESCE(cp.phone,'') LIKE ? OR COALESCE(cp.email,'') LIKE ?)))
    ORDER BY c.name LIMIT ? OFFSET ?`).bind(p.organizationId,type,type,search,search,search,search,search,search,limit,offset).all<Record<string,unknown>>();
  const count=await c.env.FINANCE_DB.prepare(`SELECT COUNT(*) total FROM contacts c WHERE c.organization_id=? AND c.archived_at IS NULL AND c.active=1
      AND (? IS NULL OR c.type=?)
      AND (c.name LIKE ? OR COALESCE(c.email,'') LIKE ? OR COALESCE(c.code,'') LIKE ? OR EXISTS(SELECT 1 FROM contact_people cp WHERE cp.organization_id=c.organization_id AND cp.contact_id=c.id AND (cp.name LIKE ? OR COALESCE(cp.phone,'') LIKE ? OR COALESCE(cp.email,'') LIKE ?)))`).bind(p.organizationId,type,type,search,search,search,search,search,search).first<{total:number}>();
  return c.json({data:{items:camelizeRows(rows.results),meta:{limit,offset,total:Number(count?.total||0)}}});
});
workRoutes.post("/contacts", workAccess("write"), async c => {
  const p=c.get("principal"),b=await c.req.json<Record<string,unknown>>(),kind=b.kind==="company"?"company":"person";
  const personName=requiredString(b.name,"name",200),companyName=cleanString(b.companyName,200),email=cleanString(b.email,320),phone=cleanString(b.phone,60),notes=cleanString(b.notes),tags=list(b.tags);
  const requestedType=String(b.type||"");const type=["customer","supplier","employee","other"].includes(requestedType)?requestedType:(kind==="company"?"customer":"other");
  const contactName=kind==="company"&&companyName?companyName:personName,id=newId("con");
  const customFields={...(b.customFields&&typeof b.customFields==="object"?b.customFields:{}),tasksWork:{kind,notes,tags}};
  await c.env.FINANCE_DB.prepare(`INSERT INTO contacts (id,organization_id,type,name,email,payment_terms_days,active,custom_fields,credit_limit_minor) VALUES (?,?,?,?,?,0,1,?,0)`).bind(id,p.organizationId,type,contactName,email,JSON.stringify(customFields)).run();
  if(phone||(kind==="company"&&personName!==contactName))await c.env.FINANCE_DB.prepare(`INSERT INTO contact_people (id,organization_id,contact_id,name,email,phone,role,is_primary) VALUES (?,?,?,?,?,?,?,1)`).bind(newId("cpr"),p.organizationId,id,personName,email,phone,kind==="company"?"Primary contact":"Contact").run();
  await auditWork(c.env.FINANCE_DB,c,"work.shared_contact.created","contact",id,undefined,{type,name:contactName,personName,email,phone});
  return c.json({data:{id,type,name:contactName,email,phone,primaryPersonName:personName}},201);
});
workRoutes.get("/contacts/:id", async c => {const p=c.get("principal"),id=c.req.param("id"),contact=await requireContact(c.env.FINANCE_DB,p.organizationId,id),people=await c.env.FINANCE_DB.prepare(`SELECT id,name,email,phone,role,is_primary FROM contact_people WHERE organization_id=? AND contact_id=? ORDER BY is_primary DESC,name`).bind(p.organizationId,id).all<Record<string,unknown>>();return c.json({data:{...camelize(contact),people:camelizeRows(people.results)}})});
workRoutes.get("/contacts/:id/people", async c => {const p=c.get("principal"),id=c.req.param("id");await requireContact(c.env.FINANCE_DB,p.organizationId,id);const r=await c.env.FINANCE_DB.prepare(`SELECT id,name,email,phone,role,is_primary FROM contact_people WHERE organization_id=? AND contact_id=? ORDER BY is_primary DESC,name`).bind(p.organizationId,id).all<Record<string,unknown>>();return c.json({data:camelizeRows(r.results)})});
workRoutes.patch("/contacts/:id", workAccess("write"), async c => {const p=c.get("principal"),id=c.req.param("id"),before=await requireContact(c.env.FINANCE_DB,p.organizationId,id),b=await c.req.json<Record<string,unknown>>();const name=cleanString(b.name,200),email=Object.hasOwn(b,"email")?cleanString(b.email,320):undefined,type=Object.hasOwn(b,"type")&&["customer","supplier","employee","other"].includes(String(b.type))?String(b.type):null;await c.env.FINANCE_DB.prepare(`UPDATE contacts SET name=COALESCE(?,name),email=CASE WHEN ? THEN ? ELSE email END,type=COALESCE(?,type),updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=? AND archived_at IS NULL`).bind(name,Object.hasOwn(b,"email")?1:0,email??null,type,id,p.organizationId).run();if(Object.hasOwn(b,"phone")){const primary=await c.env.FINANCE_DB.prepare(`SELECT id FROM contact_people WHERE organization_id=? AND contact_id=? ORDER BY is_primary DESC,created_at LIMIT 1`).bind(p.organizationId,id).first<{id:string}>();if(primary)await c.env.FINANCE_DB.prepare(`UPDATE contact_people SET phone=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(cleanString(b.phone,60),primary.id).run();else if(cleanString(b.phone,60))await c.env.FINANCE_DB.prepare(`INSERT INTO contact_people (id,organization_id,contact_id,name,email,phone,role,is_primary) VALUES (?,?,?,?,?,?,?,1)`).bind(newId("cpr"),p.organizationId,id,name||String(before.name||"Contact"),email??before.email??null,cleanString(b.phone,60),"Contact").run()}await auditWork(c.env.FINANCE_DB,c,"work.shared_contact.updated","contact",id,before,b);return c.json({data:{id,updated:true}})});
workRoutes.delete("/contacts/:id", workAccess("manage"), async c => {const p=c.get("principal"),id=c.req.param("id");await requireContact(c.env.FINANCE_DB,p.organizationId,id);await c.env.FINANCE_DB.prepare("UPDATE contacts SET active=0,archived_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=?").bind(id,p.organizationId).run();await auditWork(c.env.FINANCE_DB,c,"work.shared_contact.archived","contact",id);return c.json({data:{archived:true}})});

// PROJECTS
workRoutes.get("/projects", async c => {
  const p=c.get("principal"),limit=parseLimit(c),offset=parseOffset(c),status=c.req.query("status")||null,teamId=c.req.query("teamId")||null,search=`%${c.req.query("search")||""}%`;
  const rows=await c.env.FINANCE_DB.prepare(`SELECT pj.*,u.display_name owner_name,t.name team_name,wc.name contact_name,
    (SELECT COUNT(*) FROM work_tasks x WHERE x.project_id=pj.id AND x.archived_at IS NULL) task_count,
    (SELECT COUNT(*) FROM work_project_members pm WHERE pm.project_id=pj.id) member_count
    FROM work_projects pj LEFT JOIN users u ON u.id=pj.owner_user_id LEFT JOIN work_teams t ON t.id=pj.team_id LEFT JOIN contacts wc ON wc.id=pj.ledger_contact_id
    WHERE pj.organization_id=? AND pj.archived_at IS NULL AND (? IS NULL OR pj.status=?) AND (? IS NULL OR pj.team_id=?) AND (pj.name LIKE ? OR pj.code LIKE ?)
    ORDER BY pj.updated_at DESC LIMIT ? OFFSET ?`).bind(p.organizationId,status,status,teamId,teamId,search,search,limit,offset).all<Record<string,unknown>>();
  const count=await c.env.FINANCE_DB.prepare(`SELECT COUNT(*) total FROM work_projects WHERE organization_id=? AND archived_at IS NULL AND (? IS NULL OR status=?) AND (? IS NULL OR team_id=?) AND (name LIKE ? OR code LIKE ?)`).bind(p.organizationId,status,status,teamId,teamId,search,search).first<{total:number}>();
  return c.json({data:{items:camelizeRows(rows.results),meta:{limit,offset,total:Number(count?.total||0)}}});
});
workRoutes.post("/projects", workAccess("write"), async c => {
  const p=c.get("principal"),b=await c.req.json<Record<string,unknown>>(),id=newId("wpj"),code=requiredString(b.code,"code",40).toUpperCase(),name=requiredString(b.name,"name",200),teamId=cleanString(b.teamId,100),contactId=cleanString(b.contactId,100),ownerUserId=cleanString(b.ownerUserId,100)||actor(c),financeProjectId=cleanString(b.financeProjectId,100);
  if(teamId)await requireTeam(c.env.FINANCE_DB,p.organizationId,teamId);if(contactId)await requireContact(c.env.FINANCE_DB,p.organizationId,contactId);if(ownerUserId)await requireOrgUser(c.env.FINANCE_DB,p.organizationId,ownerUserId,"Project owner");if(financeProjectId&&!await c.env.FINANCE_DB.prepare("SELECT 1 FROM projects WHERE id=? AND organization_id=?").bind(financeProjectId,p.organizationId).first())throw new AppError(422,"INVALID_REFERENCE","Linked Ledgerly project is invalid");
  const priority=choice(b.priority,PRIORITIES,"medium"),status=choice(b.status,PROJECT_STATUSES,"planning"),description=cleanString(b.description),startDate=cleanString(b.startDate,20),dueDate=cleanString(b.dueDate,20);
  await c.env.FINANCE_DB.prepare(`INSERT INTO work_projects (id,organization_id,finance_project_id,team_id,contact_id,ledger_contact_id,code,name,description,status,priority,owner_user_id,start_date,due_date,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,p.organizationId,financeProjectId,teamId,null,contactId,code,name,description,status,priority,ownerUserId,startDate,dueDate,actor(c)).run();
  if(ownerUserId)await c.env.FINANCE_DB.prepare("INSERT OR IGNORE INTO work_project_members (project_id,user_id,role) VALUES (?,?,'owner')").bind(id,ownerUserId).run();await auditWork(c.env.FINANCE_DB,c,"work.project.created","work_project",id,undefined,{code,name,status,priority,teamId,contactId});return c.json({data:{id,code,name,status,priority,teamId,contactId,ownerUserId}},201);
});
workRoutes.get("/projects/:id", async c => {const p=c.get("principal"),id=c.req.param("id"),project=await requireProject(c.env.FINANCE_DB,p.organizationId,id);const [members,tasks]=await Promise.all([c.env.FINANCE_DB.prepare(`SELECT u.id,u.display_name AS full_name,u.email,pm.role FROM work_project_members pm JOIN users u ON u.id=pm.user_id WHERE pm.project_id=? ORDER BY u.display_name`).bind(id).all<Record<string,unknown>>(),c.env.FINANCE_DB.prepare(`SELECT id,task_number,title,status,priority,due_at,progress FROM work_tasks WHERE project_id=? AND organization_id=? AND archived_at IS NULL ORDER BY updated_at DESC LIMIT 100`).bind(id,p.organizationId).all<Record<string,unknown>>()]);return c.json({data:{...camelize(project),members:camelizeRows(members.results),tasks:camelizeRows(tasks.results)}})});
workRoutes.patch("/projects/:id", workAccess("write"), async c => {const p=c.get("principal"),id=c.req.param("id"),before=await requireProject(c.env.FINANCE_DB,p.organizationId,id),b=await c.req.json<Record<string,unknown>>();const status=Object.hasOwn(b,"status")?choice(b.status,PROJECT_STATUSES,"planning"):null,priority=Object.hasOwn(b,"priority")?choice(b.priority,PRIORITIES,"medium"):null;await c.env.FINANCE_DB.prepare(`UPDATE work_projects SET name=COALESCE(?,name),description=CASE WHEN ? THEN ? ELSE description END,status=COALESCE(?,status),priority=COALESCE(?,priority),start_date=CASE WHEN ? THEN ? ELSE start_date END,due_date=CASE WHEN ? THEN ? ELSE due_date END,progress=COALESCE(?,progress),updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=?`).bind(cleanString(b.name,200),Object.hasOwn(b,"description")?1:0,cleanString(b.description),status,priority,Object.hasOwn(b,"startDate")?1:0,cleanString(b.startDate,20),Object.hasOwn(b,"dueDate")?1:0,cleanString(b.dueDate,20),typeof b.progress==="number"?Math.max(0,Math.min(100,Math.trunc(b.progress))):null,id,p.organizationId).run();await auditWork(c.env.FINANCE_DB,c,"work.project.updated","work_project",id,before,b);return c.json({data:{id,updated:true}})});
workRoutes.post("/projects/:id/members", workAccess("write"), async c => {const p=c.get("principal"),projectId=c.req.param("id"),b=await c.req.json<Record<string,unknown>>();await requireProject(c.env.FINANCE_DB,p.organizationId,projectId);const userId=requiredString(b.userId,"userId",100);await requireOrgUser(c.env.FINANCE_DB,p.organizationId,userId);const role=choice(b.role,["owner","manager","member","viewer"] as const,"member");await c.env.FINANCE_DB.prepare("INSERT INTO work_project_members (project_id,user_id,role) VALUES (?,?,?) ON CONFLICT(project_id,user_id) DO UPDATE SET role=excluded.role").bind(projectId,userId,role).run();return c.json({data:{projectId,userId,role}})});
