// TASKS
workRoutes.get("/tasks", async c => {
  const p=c.get("principal"),limit=parseLimit(c),offset=parseOffset(c),status=c.req.query("status")||null,projectId=c.req.query("projectId")||null,assigneeId=c.req.query("assigneeId")||null,parentTaskId=c.req.query("parentTaskId")||null,search=`%${c.req.query("search")||""}%`;
  const rows=await c.env.FINANCE_DB.prepare(`SELECT DISTINCT t.*,pj.name project_name,
    (SELECT COUNT(*) FROM work_task_checklist_items ci WHERE ci.task_id=t.id) checklist_total,
    (SELECT COUNT(*) FROM work_task_checklist_items ci WHERE ci.task_id=t.id AND ci.is_completed=1) checklist_completed,
    (SELECT COUNT(*) FROM work_comments cm WHERE cm.task_id=t.id AND cm.deleted_at IS NULL) comment_count
    FROM work_tasks t LEFT JOIN work_projects pj ON pj.id=t.project_id LEFT JOIN work_task_assignees ta ON ta.task_id=t.id
    WHERE t.organization_id=? AND t.archived_at IS NULL AND (? IS NULL OR t.status=?) AND (? IS NULL OR t.project_id=?) AND (? IS NULL OR ta.user_id=?) AND (? IS NULL OR t.parent_task_id=?) AND (t.title LIKE ? OR COALESCE(t.description,'') LIKE ?)
    ORDER BY CASE t.priority WHEN 'urgent' THEN 1 WHEN 'high' THEN 2 WHEN 'medium' THEN 3 ELSE 4 END,t.due_at IS NULL,t.due_at,t.updated_at DESC LIMIT ? OFFSET ?`).bind(p.organizationId,status,status,projectId,projectId,assigneeId,assigneeId,parentTaskId,parentTaskId,search,search,limit,offset).all<Record<string,unknown>>();
  const count=await c.env.FINANCE_DB.prepare(`SELECT COUNT(DISTINCT t.id) total FROM work_tasks t LEFT JOIN work_task_assignees ta ON ta.task_id=t.id WHERE t.organization_id=? AND t.archived_at IS NULL AND (? IS NULL OR t.status=?) AND (? IS NULL OR t.project_id=?) AND (? IS NULL OR ta.user_id=?) AND (? IS NULL OR t.parent_task_id=?) AND (t.title LIKE ? OR COALESCE(t.description,'') LIKE ?)`).bind(p.organizationId,status,status,projectId,projectId,assigneeId,assigneeId,parentTaskId,parentTaskId,search,search).first<{total:number}>();
  return c.json({data:{items:camelizeRows(rows.results),meta:{limit,offset,total:Number(count?.total||0)}}});
});
workRoutes.post("/tasks", workAccess("write"), async c => {
  const p=c.get("principal"),b=await c.req.json<Record<string,unknown>>(),id=newId("wts"),number=await nextTaskNumber(c.env.FINANCE_DB,p.organizationId),title=requiredString(b.title,"title",500),projectId=cleanString(b.projectId,100),parentTaskId=cleanString(b.parentTaskId,100);
  if(projectId)await requireProject(c.env.FINANCE_DB,p.organizationId,projectId);if(parentTaskId)await requireTask(c.env.FINANCE_DB,p.organizationId,parentTaskId);
  const status=choice(b.status,TASK_STATUSES,"todo"),priority=choice(b.priority,PRIORITIES,"medium"),description=cleanString(b.description),startAt=cleanString(b.startAt,40),dueAt=cleanString(b.dueAt,40),estimate=typeof b.estimatedMinutes==="number"?Math.max(0,Math.trunc(b.estimatedMinutes)):null;
  await c.env.FINANCE_DB.prepare(`INSERT INTO work_tasks (id,organization_id,project_id,parent_task_id,task_number,title,description,status,priority,start_at,due_at,estimated_minutes,recurrence_json,custom_fields_json,created_by,updated_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,p.organizationId,projectId,parentTaskId,number,title,description,status,priority,startAt,dueAt,estimate,b.recurrence?JSON.stringify(b.recurrence):null,JSON.stringify(b.customFields&&typeof b.customFields==="object"?b.customFields:{}),actor(c),actor(c)).run();
  const assignees=list(b.assigneeIds);for(const userId of assignees){try{await requireOrgUser(c.env.FINANCE_DB,p.organizationId,userId);await c.env.FINANCE_DB.prepare("INSERT OR IGNORE INTO work_task_assignees (task_id,user_id,assigned_by) VALUES (?,?,?)").bind(id,userId,actor(c)).run();if(userId!==p.userId)await notifyWork(c.env,{organizationId:p.organizationId,userId,eventType:"task.assigned",title:"New task assigned",body:`You were assigned task #${number}: ${title}`,entityType:"task",entityId:id});}catch{/* Ignore invalid assignee IDs as original app did. */}}
  for(const userId of list(b.followerIds)){try{await requireOrgUser(c.env.FINANCE_DB,p.organizationId,userId);await c.env.FINANCE_DB.prepare("INSERT OR IGNORE INTO work_task_followers (task_id,user_id) VALUES (?,?)").bind(id,userId).run()}catch{}}
  if(projectId&&actor(c))await c.env.FINANCE_DB.prepare("INSERT OR IGNORE INTO work_project_members (project_id,user_id,role) VALUES (?,?,'member')").bind(projectId,actor(c)).run();
  await auditWork(c.env.FINANCE_DB,c,"work.task.created","work_task",id,undefined,{taskNumber:number,title,status,priority,projectId,parentTaskId,assignees});return c.json({data:{id,taskNumber:number,title,status,priority,projectId,parentTaskId}},201);
});
async function taskDetail(c: WorkContext,id:string){const p=c.get("principal"),task=await requireTask(c.env.FINANCE_DB,p.organizationId,id);const [assignees,followers,checklist,comments,time,subtasks]=await Promise.all([
  c.env.FINANCE_DB.prepare(`SELECT u.id,u.display_name AS full_name,u.email,a.assigned_at FROM work_task_assignees a JOIN users u ON u.id=a.user_id WHERE a.task_id=? ORDER BY u.display_name`).bind(id).all<Record<string,unknown>>(),
  c.env.FINANCE_DB.prepare(`SELECT u.id,u.display_name AS full_name,u.email FROM work_task_followers f JOIN users u ON u.id=f.user_id WHERE f.task_id=? ORDER BY u.display_name`).bind(id).all<Record<string,unknown>>(),
  c.env.FINANCE_DB.prepare("SELECT * FROM work_task_checklist_items WHERE task_id=? ORDER BY position,created_at").bind(id).all<Record<string,unknown>>(),
  c.env.FINANCE_DB.prepare(`SELECT cm.*,u.display_name author_name FROM work_comments cm LEFT JOIN users u ON u.id=cm.author_user_id WHERE cm.task_id=? AND cm.organization_id=? AND cm.deleted_at IS NULL ORDER BY cm.created_at`).bind(id,p.organizationId).all<Record<string,unknown>>(),
  c.env.FINANCE_DB.prepare(`SELECT te.*,u.display_name user_name FROM work_time_entries te JOIN users u ON u.id=te.user_id WHERE te.task_id=? AND te.organization_id=? ORDER BY te.started_at DESC`).bind(id,p.organizationId).all<Record<string,unknown>>(),
  c.env.FINANCE_DB.prepare(`SELECT id,task_number,title,status,priority,due_at,progress FROM work_tasks WHERE parent_task_id=? AND organization_id=? AND archived_at IS NULL ORDER BY created_at`).bind(id,p.organizationId).all<Record<string,unknown>>(),
]);return {...camelize(task),assignees:camelizeRows(assignees.results),followers:camelizeRows(followers.results),checklist:camelizeRows(checklist.results),comments:camelizeRows(comments.results),timeEntries:camelizeRows(time.results),subtasks:camelizeRows(subtasks.results)}}
workRoutes.get("/tasks/:id", async c => c.json({data:await taskDetail(c,c.req.param("id"))}));
workRoutes.patch("/tasks/:id", workAccess("write"), async c => {const p=c.get("principal"),id=c.req.param("id"),before=await requireTask(c.env.FINANCE_DB,p.organizationId,id),b=await c.req.json<Record<string,unknown>>(),projectId=Object.hasOwn(b,"projectId")?cleanString(b.projectId,100):undefined,parentTaskId=Object.hasOwn(b,"parentTaskId")?cleanString(b.parentTaskId,100):undefined;if(projectId)await requireProject(c.env.FINANCE_DB,p.organizationId,projectId);if(parentTaskId){if(parentTaskId===id)throw new AppError(422,"INVALID_PARENT","A task cannot be its own parent");await requireTask(c.env.FINANCE_DB,p.organizationId,parentTaskId)}const status=Object.hasOwn(b,"status")?choice(b.status,TASK_STATUSES,"todo"):null,priority=Object.hasOwn(b,"priority")?choice(b.priority,PRIORITIES,"medium"):null,progress=typeof b.progress==="number"?Math.max(0,Math.min(100,Math.trunc(b.progress))):null;await c.env.FINANCE_DB.prepare(`UPDATE work_tasks SET title=COALESCE(?,title),description=CASE WHEN ? THEN ? ELSE description END,status=COALESCE(?,status),priority=COALESCE(?,priority),project_id=CASE WHEN ? THEN ? ELSE project_id END,parent_task_id=CASE WHEN ? THEN ? ELSE parent_task_id END,start_at=CASE WHEN ? THEN ? ELSE start_at END,due_at=CASE WHEN ? THEN ? ELSE due_at END,estimated_minutes=CASE WHEN ? THEN ? ELSE estimated_minutes END,progress=COALESCE(?,progress),completed_at=CASE WHEN ?='completed' THEN COALESCE(completed_at,CURRENT_TIMESTAMP) WHEN ? IS NOT NULL THEN NULL ELSE completed_at END,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=?`).bind(cleanString(b.title,500),Object.hasOwn(b,"description")?1:0,cleanString(b.description),status,priority,Object.hasOwn(b,"projectId")?1:0,projectId??null,Object.hasOwn(b,"parentTaskId")?1:0,parentTaskId??null,Object.hasOwn(b,"startAt")?1:0,cleanString(b.startAt,40),Object.hasOwn(b,"dueAt")?1:0,cleanString(b.dueAt,40),Object.hasOwn(b,"estimatedMinutes")?1:0,typeof b.estimatedMinutes==="number"?Math.max(0,Math.trunc(b.estimatedMinutes)):null,progress,status,status,actor(c),id,p.organizationId).run();await auditWork(c.env.FINANCE_DB,c,"work.task.updated","work_task",id,before,b);return c.json({data:await taskDetail(c,id)})});
workRoutes.patch("/tasks/:id/status", workAccess("write"), async c => {const p=c.get("principal"),id=c.req.param("id"),before=await requireTask(c.env.FINANCE_DB,p.organizationId,id),b=await c.req.json<Record<string,unknown>>(),status=choice(b.status,TASK_STATUSES,"todo");await c.env.FINANCE_DB.prepare(`UPDATE work_tasks SET status=?,progress=CASE WHEN ?='completed' THEN 100 ELSE progress END,completed_at=CASE WHEN ?='completed' THEN CURRENT_TIMESTAMP ELSE NULL END,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=?`).bind(status,status,status,actor(c),id,p.organizationId).run();const audience=await c.env.FINANCE_DB.prepare(`SELECT user_id FROM work_task_assignees WHERE task_id=? UNION SELECT user_id FROM work_task_followers WHERE task_id=?`).bind(id,id).all<{user_id:string}>();for(const row of audience.results){if(row.user_id!==p.userId)await notifyWork(c.env,{organizationId:p.organizationId,userId:row.user_id,eventType:"task.status_changed",title:`Task #${before.task_number} updated`,body:`${before.title} is now ${status.replaceAll("_"," ")}`,entityType:"task",entityId:id})}await auditWork(c.env.FINANCE_DB,c,"work.task.status_changed","work_task",id,before,{status});return c.json({data:await taskDetail(c,id)})});
workRoutes.delete("/tasks/:id", workAccess("write"), async c => {const p=c.get("principal"),id=c.req.param("id");await requireTask(c.env.FINANCE_DB,p.organizationId,id);await c.env.FINANCE_DB.prepare("UPDATE work_tasks SET archived_at=CURRENT_TIMESTAMP,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=?").bind(actor(c),id,p.organizationId).run();return c.json({data:{archived:true}})});

