workRoutes.post("/tasks/:id/checklist", workAccess("write"), async c => {const p=c.get("principal"),taskId=c.req.param("id"),b=await c.req.json<Record<string,unknown>>(),id=newId("wci");await requireTask(c.env.FINANCE_DB,p.organizationId,taskId);const title=requiredString(b.title,"title",500),position=typeof b.position==="number"?Math.trunc(b.position):0;await c.env.FINANCE_DB.prepare("INSERT INTO work_task_checklist_items (id,task_id,title,position) VALUES (?,?,?,?)").bind(id,taskId,title,position).run();return c.json({data:{id,taskId,title,position,isCompleted:false}},201)});
workRoutes.patch("/tasks/:taskId/checklist/:id", workAccess("write"), async c => {const p=c.get("principal"),taskId=c.req.param("taskId"),id=c.req.param("id"),b=await c.req.json<Record<string,unknown>>();await requireTask(c.env.FINANCE_DB,p.organizationId,taskId);const completed=Object.hasOwn(b,"isCompleted")?parseBool(b.isCompleted):null;const r=await c.env.FINANCE_DB.prepare(`UPDATE work_task_checklist_items SET title=COALESCE(?,title),position=COALESCE(?,position),is_completed=COALESCE(?,is_completed),completed_by=CASE WHEN ?=1 THEN ? WHEN ?=0 THEN NULL ELSE completed_by END,completed_at=CASE WHEN ?=1 THEN CURRENT_TIMESTAMP WHEN ?=0 THEN NULL ELSE completed_at END,updated_at=CURRENT_TIMESTAMP WHERE id=? AND task_id=?`).bind(cleanString(b.title,500),typeof b.position==="number"?Math.trunc(b.position):null,completed===null?null:completed?1:0,completed===null?null:completed?1:0,actor(c),completed===null?null:completed?1:0,completed===null?null:completed?1:0,completed===null?null:completed?1:0,id,taskId).run();if(!r.meta.changes)throw new AppError(404,"CHECKLIST_NOT_FOUND","Checklist item not found");return c.json({data:{id,updated:true}})});
workRoutes.delete("/tasks/:taskId/checklist/:id", workAccess("write"), async c => {const p=c.get("principal"),taskId=c.req.param("taskId");await requireTask(c.env.FINANCE_DB,p.organizationId,taskId);await c.env.FINANCE_DB.prepare("DELETE FROM work_task_checklist_items WHERE id=? AND task_id=?").bind(c.req.param("id"),taskId).run();return c.json({data:{deleted:true}})});

