workRoutes.get("/tasks/:id/comments", async c => {const p=c.get("principal"),id=c.req.param("id");await requireTask(c.env.FINANCE_DB,p.organizationId,id);const r=await c.env.FINANCE_DB.prepare(`SELECT cm.*,u.display_name author_name FROM work_comments cm LEFT JOIN users u ON u.id=cm.author_user_id WHERE cm.task_id=? AND cm.organization_id=? AND cm.deleted_at IS NULL ORDER BY cm.created_at`).bind(id,p.organizationId).all<Record<string,unknown>>();return c.json({data:camelizeRows(r.results)})});
workRoutes.post("/tasks/:id/comments", workAccess("write"), async c => {const p=c.get("principal"),taskId=c.req.param("id"),task=await requireTask(c.env.FINANCE_DB,p.organizationId,taskId),b=await c.req.json<Record<string,unknown>>(),id=newId("wcm"),body=requiredString(b.body,"body",10000),mentions=list(b.mentionUserIds);const valid:string[]=[];for(const userId of mentions){try{await requireOrgUser(c.env.FINANCE_DB,p.organizationId,userId);valid.push(userId)}catch{}}await c.env.FINANCE_DB.prepare("INSERT INTO work_comments (id,organization_id,task_id,author_user_id,body,mentions_json) VALUES (?,?,?,?,?,?)").bind(id,p.organizationId,taskId,actor(c),body,JSON.stringify(valid)).run();for(const userId of new Set(valid)){if(userId!==p.userId)await notifyWork(c.env,{organizationId:p.organizationId,userId,eventType:"comment.mentioned",title:"You were mentioned",body:`You were mentioned on task #${task.task_number}: ${task.title}`,entityType:"task",entityId:taskId})}return c.json({data:{id,taskId,body,mentions:valid}},201)});
workRoutes.patch("/tasks/:taskId/comments/:id", workAccess("write"), async c => {const p=c.get("principal"),taskId=c.req.param("taskId"),id=c.req.param("id"),b=await c.req.json<Record<string,unknown>>();await requireTask(c.env.FINANCE_DB,p.organizationId,taskId);const r=await c.env.FINANCE_DB.prepare("UPDATE work_comments SET body=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND task_id=? AND organization_id=? AND (author_user_id=? OR ? IN ('owner','admin')) AND deleted_at IS NULL").bind(requiredString(b.body,"body",10000),id,taskId,p.organizationId,actor(c),p.role).run();if(!r.meta.changes)throw new AppError(404,"COMMENT_NOT_FOUND","Comment not found or cannot be edited");return c.json({data:{id,updated:true}})});
workRoutes.delete("/tasks/:taskId/comments/:id", workAccess("write"), async c => {const p=c.get("principal"),taskId=c.req.param("taskId"),id=c.req.param("id");await requireTask(c.env.FINANCE_DB,p.organizationId,taskId);const r=await c.env.FINANCE_DB.prepare("UPDATE work_comments SET deleted_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=? AND task_id=? AND organization_id=? AND (author_user_id=? OR ? IN ('owner','admin'))").bind(id,taskId,p.organizationId,actor(c),p.role).run();if(!r.meta.changes)throw new AppError(404,"COMMENT_NOT_FOUND","Comment not found or cannot be deleted");return c.json({data:{deleted:true}})});

// TIME TRACKING
workRoutes.get("/tasks/:id/time-entries", async c => {const p=c.get("principal"),id=c.req.param("id");await requireTask(c.env.FINANCE_DB,p.organizationId,id);const r=await c.env.FINANCE_DB.prepare(`SELECT te.*,u.display_name user_name FROM work_time_entries te JOIN users u ON u.id=te.user_id WHERE te.task_id=? AND te.organization_id=? ORDER BY te.started_at DESC`).bind(id,p.organizationId).all<Record<string,unknown>>();return c.json({data:camelizeRows(r.results)})});
workRoutes.post("/tasks/:id/time-entries", workAccess("write"), async c => {const p=c.get("principal"),taskId=c.req.param("id"),b=await c.req.json<Record<string,unknown>>(),id=newId("wte"),userId=cleanString(b.userId,100)||actor(c);await requireTask(c.env.FINANCE_DB,p.organizationId,taskId);if(!userId)throw new AppError(422,"INVALID_USER","A real user is required for time tracking");await requireOrgUser(c.env.FINANCE_DB,p.organizationId,userId);const startedAt=requiredString(b.startedAt,"startedAt",40),endedAt=cleanString(b.endedAt,40),minutes=typeof b.minutes==="number"?Math.max(0,Math.trunc(b.minutes)):endedAt?Math.max(0,Math.round((new Date(endedAt).getTime()-new Date(startedAt).getTime())/60000)):0,billable=parseBool(b.billable);await c.env.FINANCE_DB.prepare("INSERT INTO work_time_entries (id,organization_id,task_id,user_id,description,started_at,ended_at,minutes,billable) VALUES (?,?,?,?,?,?,?,?,?)").bind(id,p.organizationId,taskId,userId,cleanString(b.description,1000),startedAt,endedAt,minutes,billable?1:0).run();await c.env.FINANCE_DB.prepare("UPDATE work_tasks SET actual_minutes=(SELECT COALESCE(SUM(minutes),0) FROM work_time_entries WHERE task_id=?),updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(taskId,taskId).run();return c.json({data:{id,taskId,userId,startedAt,endedAt,minutes,billable}},201)});
workRoutes.patch("/tasks/:taskId/time-entries/:id", workAccess("write"), async c => {const p=c.get("principal"),taskId=c.req.param("taskId"),id=c.req.param("id"),b=await c.req.json<Record<string,unknown>>();await requireTask(c.env.FINANCE_DB,p.organizationId,taskId);const r=await c.env.FINANCE_DB.prepare(`UPDATE work_time_entries SET description=CASE WHEN ? THEN ? ELSE description END,started_at=COALESCE(?,started_at),ended_at=CASE WHEN ? THEN ? ELSE ended_at END,minutes=COALESCE(?,minutes),billable=COALESCE(?,billable),updated_at=CURRENT_TIMESTAMP WHERE id=? AND task_id=? AND organization_id=? AND (user_id=? OR ? IN ('owner','admin'))`).bind(Object.hasOwn(b,"description")?1:0,cleanString(b.description,1000),cleanString(b.startedAt,40),Object.hasOwn(b,"endedAt")?1:0,cleanString(b.endedAt,40),typeof b.minutes==="number"?Math.max(0,Math.trunc(b.minutes)):null,Object.hasOwn(b,"billable")?(parseBool(b.billable)?1:0):null,id,taskId,p.organizationId,actor(c),p.role).run();if(!r.meta.changes)throw new AppError(404,"TIME_ENTRY_NOT_FOUND","Time entry not found or cannot be edited");await c.env.FINANCE_DB.prepare("UPDATE work_tasks SET actual_minutes=(SELECT COALESCE(SUM(minutes),0) FROM work_time_entries WHERE task_id=?),updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(taskId,taskId).run();return c.json({data:{id,updated:true}})});
workRoutes.delete("/tasks/:taskId/time-entries/:id", workAccess("write"), async c => {const p=c.get("principal"),taskId=c.req.param("taskId"),id=c.req.param("id");await requireTask(c.env.FINANCE_DB,p.organizationId,taskId);const r=await c.env.FINANCE_DB.prepare("DELETE FROM work_time_entries WHERE id=? AND task_id=? AND organization_id=? AND (user_id=? OR ? IN ('owner','admin'))").bind(id,taskId,p.organizationId,actor(c),p.role).run();if(!r.meta.changes)throw new AppError(404,"TIME_ENTRY_NOT_FOUND","Time entry not found or cannot be deleted");await c.env.FINANCE_DB.prepare("UPDATE work_tasks SET actual_minutes=(SELECT COALESCE(SUM(minutes),0) FROM work_time_entries WHERE task_id=?),updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(taskId,taskId).run();return c.json({data:{deleted:true}})});

// NOTIFICATIONS / PREFERENCES / DELIVERY HISTORY
workRoutes.get("/notifications", async c => {const p=c.get("principal"),limit=parseLimit(c),offset=parseOffset(c),unread=c.req.query("unread")==="true";const rows=await c.env.FINANCE_DB.prepare(`SELECT * FROM work_notifications WHERE organization_id=? AND user_id=? AND (?=0 OR read_at IS NULL) ORDER BY created_at DESC LIMIT ? OFFSET ?`).bind(p.organizationId,p.userId,unread?1:0,limit,offset).all<Record<string,unknown>>();const count=await c.env.FINANCE_DB.prepare(`SELECT COUNT(*) total FROM work_notifications WHERE organization_id=? AND user_id=? AND (?=0 OR read_at IS NULL)`).bind(p.organizationId,p.userId,unread?1:0).first<{total:number}>();return c.json({data:{items:camelizeRows(rows.results),meta:{limit,offset,total:Number(count?.total||0)}}})});
workRoutes.post("/notifications/:id/read", async c => {const p=c.get("principal"),r=await c.env.FINANCE_DB.prepare("UPDATE work_notifications SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP) WHERE id=? AND organization_id=? AND user_id=?").bind(c.req.param("id"),p.organizationId,p.userId).run();if(!r.meta.changes)throw new AppError(404,"NOTIFICATION_NOT_FOUND","Notification not found");return c.json({data:{read:true}})});
workRoutes.post("/notifications/read-all", async c => {const p=c.get("principal"),r=await c.env.FINANCE_DB.prepare("UPDATE work_notifications SET read_at=CURRENT_TIMESTAMP WHERE organization_id=? AND user_id=? AND read_at IS NULL").bind(p.organizationId,p.userId).run();return c.json({data:{updated:r.meta.changes}})});
workRoutes.get("/notification-preferences", async c => {const p=c.get("principal"),r=await c.env.FINANCE_DB.prepare("SELECT * FROM work_notification_preferences WHERE organization_id=? AND user_id=? ORDER BY event_type").bind(p.organizationId,p.userId).all<Record<string,unknown>>();return c.json({data:camelizeRows(r.results)})});
workRoutes.put("/notification-preferences/:eventType", async c => {const p=c.get("principal"),b=await c.req.json<Record<string,unknown>>(),eventType=c.req.param("eventType");await c.env.FINANCE_DB.prepare(`INSERT INTO work_notification_preferences (organization_id,user_id,event_type,in_app,email,sms,whatsapp,quiet_hours_json) VALUES (?,?,?,?,?,?,?,?) ON CONFLICT(organization_id,user_id,event_type) DO UPDATE SET in_app=excluded.in_app,email=excluded.email,sms=excluded.sms,whatsapp=excluded.whatsapp,quiet_hours_json=excluded.quiet_hours_json`).bind(p.organizationId,p.userId,eventType,parseBool(b.inApp,true)?1:0,parseBool(b.email,true)?1:0,parseBool(b.sms)?1:0,parseBool(b.whatsapp)?1:0,b.quietHours?JSON.stringify(b.quietHours):null).run();return c.json({data:{eventType,inApp:parseBool(b.inApp,true),email:parseBool(b.email,true),sms:parseBool(b.sms),whatsapp:parseBool(b.whatsapp),quietHours:b.quietHours||null}})});
workRoutes.get("/notification-deliveries", workAccess("manage"), async c => {const p=c.get("principal"),limit=parseLimit(c),offset=parseOffset(c),status=c.req.query("status")||null;const r=await c.env.FINANCE_DB.prepare(`SELECT d.*,n.title,n.event_type FROM work_notification_deliveries d JOIN work_notifications n ON n.id=d.notification_id WHERE d.organization_id=? AND (? IS NULL OR d.status=?) ORDER BY d.created_at DESC LIMIT ? OFFSET ?`).bind(p.organizationId,status,status,limit,offset).all<Record<string,unknown>>();return c.json({data:camelizeRows(r.results)})});

// UNIFIED INTERNAL + WHATSAPP CHAT
workRoutes.get("/chats",async c=>{const p=c.get("principal"),search=`%${c.req.query("search")||""}%`;const rows=await c.env.FINANCE_DB.prepare(`SELECT t.*,cp.unread_count,u.display_name created_by_name,(SELECT body FROM work_chat_messages WHERE thread_id=t.id ORDER BY created_at DESC LIMIT 1) last_message,(SELECT COUNT(*) FROM work_chat_participants WHERE thread_id=t.id) participant_count FROM work_chat_threads t JOIN work_chat_participants cp ON cp.thread_id=t.id AND cp.user_id=? LEFT JOIN users u ON u.id=t.created_by WHERE t.organization_id=? AND (t.title LIKE ? OR COALESCE(t.external_name,'') LIKE ? OR COALESCE(t.external_phone,'') LIKE ?) ORDER BY t.last_message_at DESC LIMIT 200`).bind(p.userId,p.organizationId,search,search,search).all<Record<string,unknown>>();const unread=rows.results.reduce((n,r)=>n+Number(r.unread_count||0),0);return c.json({data:{items:camelizeRows(rows.results),unread}})});
workRoutes.post("/chats",workAccess("write"),async c=>{const p=c.get("principal"),b=await c.req.json<Record<string,unknown>>(),participantIds=list(b.participantIds).filter(id=>id!==p.userId),id=newId("wct"),title=requiredString(b.title,"title",180),taskId=cleanString(b.taskId,100);if(taskId)await requireTask(c.env.FINANCE_DB,p.organizationId,taskId);for(const uid of participantIds)await requireOrgUser(c.env.FINANCE_DB,p.organizationId,uid);if(!participantIds.length)throw new AppError(422,"PARTICIPANT_REQUIRED","Choose at least one person");const all=[p.userId,...participantIds];await c.env.FINANCE_DB.prepare(`INSERT INTO work_chat_threads(id,organization_id,kind,title,task_id,created_by) VALUES(?,?,?,?,?,?)`).bind(id,p.organizationId,"internal",title,taskId,p.userId).run();await c.env.FINANCE_DB.batch(all.map(uid=>c.env.FINANCE_DB.prepare(`INSERT INTO work_chat_participants(thread_id,user_id,last_read_at) VALUES(?,?,CURRENT_TIMESTAMP)`).bind(id,uid)));const body=cleanString(b.message,10000);if(body)await appendChatMessage(c.env,{organizationId:p.organizationId,threadId:id,senderUserId:p.userId,direction:"internal",body});if(parseBool(b.whatsapp)){for(const uid of participantIds){const member=await c.env.FINANCE_DB.prepare(`SELECT u.display_name,COALESCE(sp.phone,sf.phone) phone,o.name organization_name FROM users u JOIN organizations o ON o.id=? LEFT JOIN school_user_profiles sp ON sp.organization_id=o.id AND sp.user_id=u.id LEFT JOIN school_staff_profiles sf ON sf.organization_id=o.id AND sf.user_id=u.id AND sf.deleted_at IS NULL WHERE u.id=?`).bind(p.organizationId,uid).first<any>();if(member?.phone){const sent=await hubChat(c.env,"/v1/integrations/templates/send",{method:"POST",headers:{"Idempotency-Key":`${id}:${uid}`},body:JSON.stringify({phoneNumber:member.phone,templateName:"general_app_update",language:"en_US",variables:[member.display_name,member.organization_name,title,body||"You have a new message in Ledgerly."]})});if(sent.conversationId)await c.env.FINANCE_DB.prepare(`UPDATE work_chat_threads SET whatsapp_conversation_id=COALESCE(whatsapp_conversation_id,?),external_phone=COALESCE(external_phone,?) WHERE id=?`).bind(sent.conversationId,member.phone,id).run()}}}return c.json({data:{id}},201)});
workRoutes.get("/chats/:id",async c=>{const p=c.get("principal"),id=c.req.param("id"),thread=await ensureChatAccess(c.env.FINANCE_DB,p.organizationId,p.userId,id);const [messages,participants]=await Promise.all([c.env.FINANCE_DB.prepare(`SELECT m.*,u.display_name sender_name FROM work_chat_messages m LEFT JOIN users u ON u.id=m.sender_user_id WHERE m.thread_id=? ORDER BY m.created_at`).bind(id).all<Record<string,unknown>>(),c.env.FINANCE_DB.prepare(`SELECT u.id,u.display_name full_name,u.email,p.unread_count,p.last_read_at FROM work_chat_participants p JOIN users u ON u.id=p.user_id WHERE p.thread_id=? ORDER BY u.display_name`).bind(id).all<Record<string,unknown>>()]);await c.env.FINANCE_DB.prepare(`UPDATE work_chat_participants SET unread_count=0,last_read_at=CURRENT_TIMESTAMP WHERE thread_id=? AND user_id=?`).bind(id,p.userId).run();return c.json({data:{...camelize(thread),messages:camelizeRows(messages.results),participants:camelizeRows(participants.results)}})});
workRoutes.post("/chats/:id/read",async c=>{const p=c.get("principal");await ensureChatAccess(c.env.FINANCE_DB,p.organizationId,p.userId,c.req.param("id"));await c.env.FINANCE_DB.prepare(`UPDATE work_chat_participants SET unread_count=0,last_read_at=CURRENT_TIMESTAMP WHERE thread_id=? AND user_id=?`).bind(c.req.param("id"),p.userId).run();return c.json({data:{read:true}})});
workRoutes.post("/chats/:id/messages",workAccess("write"),async c=>{const p=c.get("principal"),id=c.req.param("id"),thread=await ensureChatAccess(c.env.FINANCE_DB,p.organizationId,p.userId,id);if(thread.status==="closed")throw new AppError(409,"CHAT_CLOSED","This session is closed. Only a new inbound WhatsApp message can reopen it.");const b=await c.req.json<Record<string,unknown>>(),body=requiredString(b.body,"message",10000),mirror=parseBool(b.whatsapp)&&Boolean(thread.whatsapp_conversation_id);let externalId:string|null=null;if(mirror){const sent=await hubChat(c.env,`/v1/integrations/conversations/${thread.whatsapp_conversation_id}/messages`,{method:"POST",headers:{"Idempotency-Key":newId("wci")},body:JSON.stringify({type:"text",message:body,senderId:p.userId})});externalId=String(sent.message?.externalMessageId||sent.message?.external_message_id||"")||null}const messageId=await appendChatMessage(c.env,{organizationId:p.organizationId,threadId:id,senderUserId:p.userId,direction:mirror?"outbound":"internal",body,externalMessageId:externalId,deliveryStatus:mirror?"sent":null});return c.json({data:{id:messageId}},201)});
workRoutes.post("/chats/:id/attachments",workAccess("write"),async c=>{const p=c.get("principal"),id=c.req.param("id"),thread=await ensureChatAccess(c.env.FINANCE_DB,p.organizationId,p.userId,id);if(thread.status==="closed")throw new AppError(409,"CHAT_CLOSED","This session is closed");const form=await c.req.formData(),part=form.get("file");if(!(part instanceof File)||!part.size)throw new AppError(422,"FILE_REQUIRED","Choose a file or record an audio note");if(part.size>20*1024*1024)throw new AppError(422,"FILE_TOO_LARGE","Chat files are limited to 20 MB");const mime=(part.type||"application/octet-stream").toLowerCase(),name=safeFileName(part.name),messageId=newId("wcm"),key=`chat/${p.organizationId}/${id}/${messageId}/${name}`;await c.env.WORK_FILES_BUCKET.put(key,await part.arrayBuffer(),{httpMetadata:{contentType:mime,contentDisposition:`inline; filename=\"${name}\"`}});await c.env.FINANCE_DB.batch([c.env.FINANCE_DB.prepare(`INSERT INTO work_chat_messages(id,organization_id,thread_id,sender_user_id,direction,message_type,body,file_key,file_name,mime_type,size_bytes) VALUES(?,?,?,?,?,?,?,?,?,?,?)`).bind(messageId,p.organizationId,id,p.userId,"internal",messageType(mime),cleanString(form.get("caption"),1000),key,name,mime,part.size),c.env.FINANCE_DB.prepare(`UPDATE work_chat_threads SET last_message_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(id),c.env.FINANCE_DB.prepare(`UPDATE work_chat_participants SET unread_count=unread_count+1 WHERE thread_id=? AND user_id<>?`).bind(id,p.userId)]);return c.json({data:{id:messageId,fileName:name,mimeType:mime,sizeBytes:part.size}},201)});
workRoutes.get("/chats/:threadId/messages/:messageId/file",async c=>{const p=c.get("principal"),threadId=c.req.param("threadId");await ensureChatAccess(c.env.FINANCE_DB,p.organizationId,p.userId,threadId);const m=await c.env.FINANCE_DB.prepare(`SELECT file_key,file_name,mime_type,size_bytes FROM work_chat_messages WHERE id=? AND thread_id=? AND organization_id=?`).bind(c.req.param("messageId"),threadId,p.organizationId).first<any>();if(!m?.file_key)throw new AppError(404,"FILE_NOT_FOUND","Attachment not found");const obj=await c.env.WORK_FILES_BUCKET.get(m.file_key);if(!obj)throw new AppError(404,"FILE_NOT_FOUND","Attachment data is missing");c.header("Content-Type",m.mime_type||"application/octet-stream");c.header("Content-Disposition",`inline; filename=\"${safeFileName(m.file_name||"attachment")}\"`);return c.body(obj.body)});
workRoutes.post("/chats/:id/close",workAccess("write"),async c=>{const p=c.get("principal"),id=c.req.param("id"),thread=await ensureChatAccess(c.env.FINANCE_DB,p.organizationId,p.userId,id);if(thread.whatsapp_conversation_id)await hubChat(c.env,`/v1/integrations/chat/sessions/${thread.whatsapp_conversation_id}/close`,{method:"POST",body:JSON.stringify({reason:"Closed in Ledgerly",closedBy:p.userId})});await c.env.FINANCE_DB.prepare(`UPDATE work_chat_threads SET status='closed',closed_by=?,closed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(p.userId,id).run();await appendChatMessage(c.env,{organizationId:p.organizationId,threadId:id,senderUserId:p.userId,direction:"internal",messageType:"system",body:"Session closed"});return c.json({data:{closed:true}})});

// AUDIT VIEW FOR WORK OPERATIONS
workRoutes.get("/audit", workAccess("manage"), async c => {const p=c.get("principal"),limit=parseLimit(c),offset=parseOffset(c);const r=await c.env.FINANCE_DB.prepare(`SELECT * FROM audit_logs WHERE organization_id=? AND entity_type LIKE 'work_%' ORDER BY created_at DESC LIMIT ? OFFSET ?`).bind(p.organizationId,limit,offset).all<Record<string,unknown>>();return c.json({data:camelizeRows(r.results)})});
